// Generated from the individually edited RU event-outcomes catalog (E291-E360).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E291_E360 = Object.freeze({"E291.1":{"s":"Король выходит против Арра и вынуждает льва признать исход поединка. Барон расплачивается золотом за неожиданно спасённый форт.","f":"Арр опрокидывает Короля на землю, причиняя тяжёлое ранение. Барон отводит глаза от поля.","v":{"nf":"Поединок прерывается без тяжёлого ранения Короля, но спор о форте остаётся открытым."}},"E291.2":{"s":"Вы возвращаете барону собственные слова, и тот вынужден лично договориться с Арром. За освобождение от королевского поединка барон платит золотом.","f":"Барон объявляет ваше требование изменой человеческой стороне и выводит охрану. Начинается стычка."},"E291.3":{"s":"Вы оплачиваете день перемирия для обоих правителей. Арр садится у границы, а барон впервые за утро разворачивает карту вместо меча."},"E291.4":{"s":"Вы отказываетесь представлять барона в чужом поединке. Арр поворачивается к тому, кого действительно вызывал."},"E292.1":{"s":"Вы покупаете у Пипа припасы, и Роах получает очередное пирожное за состоявшуюся сделку. Гоблин немедленно предлагает платную улыбку дракона."},"E292.2":{"s":"Вы добиваетесь, чтобы Роах отпустил прохожих без покупки. Пип возвращает часть неправомерно взятого золота.","f":"Дракон принимает требование за попытку лишить его пирожных и зовёт охранников киоска. Начинается стычка."},"E292.3":{"s":"{{heroName}} увлекает Роаха разговором о любимых пирожных, и покупатели успевают пройти бесплатно. Пип откупается золотом за прекращение потока жалоб.","f":"Роах резко поворачивается к отвлекающему, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Дракон пресекает отвлекающий манёвр, но никто из допустимых бойцов не получает тяжёлого ранения. Киоск продолжает требовать покупки."}},"E292.4":{"s":"Вы обходите киоск по другой стороне дороги. Роах провожает отряд взглядом, а Пип уже вывешивает цену за обход."},"E293.1":{"s":"Эдран соглашается временно принять К-12 и задаёт ему простую работу у кузницы. Благодарный автомат находит для отряда припасы.","f":"Кузнец не готов называть хозяином голема, который старше его на два века. К-12 остаётся ждать приказа."},"E293.2":{"s":"Вы отключаете К-12 без повреждения мастерской и забираете ценные детали за золото.","f":"Голем объявляет отключение нападением на владельца и поднимает металлические руки. Начинается стычка."},"E293.3":{"s":"{{heroName}} находит на пластине старую запись об имени Эдрана и скрытую золотую закладку. Кузнец получает хотя бы часть ответа.","f":"Пластина смыкается на инструментах, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Пластина защищает память механизма, но никто из допустимых бойцов не получает тяжёлого ранения. Запись остаётся загадкой."}},"E293.4":{"s":"Вы проходите мимо кузницы и не отдаёте приказов К-12. Каждые несколько шагов слышится прежнее: «Каков приказ?»"},"E294.1":{"s":"Вы разрешаете скелетам остаться на ярмарке с уже купленными билетами. Благодарные торговцы пирогами снабжают отряд припасами.","f":"Староста не решается изменить правило о признаках жизни и оставляет нежить перед воротами. Ярмарка продолжает спорить."},"E294.2":{"s":"Вы возвращаете скелетам цену билетов из своей казны. Один посетитель неохотно отдаёт ложку и идёт к выходу."},"E294.3":{"s":"{{heroName}} находит в уставе определение гостя как обладателя действительного билета, не уточняющее состояние костей. Староста платит золотом и припасами.","f":"{{heroName}} обнаруживает две противоречивые статьи о гостях и покойниках. Решение приходится отложить до следующей ярмарки."},"E294.4":{"s":"Вы оставляете ярмарку, где скелеты пытаются купить пироги, а торговцы — продать им шляпы. Староста всё ещё ищет правильный бланк."},"E295.1":{"s":"Вы заверяете разрешение на вырубку заражённого дерева, и дварфы наконец берутся за топоры. Син благодарит припасами за предотвращённую болезнь.","f":"Соседние хранители отказываются признать угрозу без доказательств. Рубку приходится остановить."},"E295.2":{"s":"Вы оставляете Сина и дварфов перед больным деревом. Никто ещё не решился первым положить топор на ствол."},"E295.3":{"s":"{{heroName}} показывает всем признаки болезни на коре и корнях, после чего Син получает право остановить заражение. Отряд награждают золотом и припасами.","f":"{{heroName}} находит признаки двух похожих болезней, но не может определить, угрожает ли одна соседним деревьям. Вырубка откладывается."},"E295.4":{"s":"Вы оплачиваете дварфам работу от имени Короля, и они убирают заражённое дерево при свидетелях. Син снабжает отряд припасами."},"E296.1":{"s":"Вы удерживаете светлый круг до рассвета, и преследователи уходят без Саара. Элион передаёт припасы за выдержанную клятву.","f":"Демоны прорывают кольцо света ещё до восхода солнца. Начинается битва."},"E296.2":{"s":"Вы принимаете золото преследователей и отходите от светлого круга. Элион остаётся один защищать безоружного Саара."},"E296.3":{"s":"Вы отдаёте преследователям золото, и они отступают до рассвета. Элион не опускает светлую границу, пока не исчезает последний демон."},"E296.4":{"s":"Вы оставляете ангела держать убежище своей клятвой. Саар молчит, пока тени преследователей удлиняются у круга."},"E297.1":{"s":"Вы помогаете посёлку укрепить дамбу у реки, и жители благодарят припасами за подготовку.","f":"Дамба не успевает подняться до нужной высоты, а на лишние работы уходят припасы. Орен всё ещё обещает наводнение."},"E297.2":{"s":"Вы помогаете устроить запасы воды на случай засухи, и жители платят золотом за предусмотрительность.","f":"Тилли не может указать, где искать воду под землёй. Подготовка не приносит награды."},"E297.3":{"s":"{{heroName}} выясняет, что оба пророка говорят о разных часах завтрашнего дня. Посёлок готовится и к воде, и к сухой земле, выдавая золото с припасами.","f":"{{heroName}} не может определить, когда именно начнётся пророческое «завтра». Посёлок остаётся между дамбой и колодцем."},"E297.4":{"s":"Вы оставляете Орена с облаками, а Тилли — с трещинами на востоке. Посёлок строит два плана на один день."},"E298.1":{"s":"Вы забираете чёрного козла из-под взглядов трёх армий и возвращаете пастуху. Тот благодарит припасами за предотвращённый бой.","f":"Один из командиров объявляет увод козла нарушением священного знака. Начинается стычка."},"E298.2":{"s":"Козёл подходит к Королю, а армии принимают это за знак остановить соперничество. Вожди выплачивают золото за неожиданное посредничество.","f":"Три армии принимают приход козла к Королю как общий вызов. Вместо тишины начинается битва."},"E298.3":{"s":"Вы оплачиваете пастуху козла и уводите его с равнины прежде, чем полководцы найдут новый повод для знамения. Животное спокойно жуёт траву."},"E298.4":{"s":"Вы расходуете припасы на обход трёх армий и одного козла. Командиры продолжают ждать, кому он уделит внимание."},"E299.1":{"s":"Вы продаёте торговцам порванные ремешки, пустые коробки и старые шнурки. В День Покупателя за это действительно дают золото.","f":"Торговцы наконец понимают, что покупают хлам, и больше не делают ставок. Продажа срывается."},"E299.2":{"s":"Вы покупаете у уставших торговцев припасы, которые они уже готовы отдать за обычную цену. Праздник для них явно затянулся."},"E299.3":{"s":"{{heroName}} находит покупателя, который готов предложить больше всех за сломанную походную ложку. Отряд получает золото.","f":"{{heroName}} опаздывает: самый отчаянный торговец уже потратил последние монеты. Выгодной сделки нет."},"E299.4":{"s":"Вы оставляете рынок, где все хотят купить чужие ненужные вещи. За спиной два торговца спорят о погнутой вилке."},"E300.1":{"s":"Вы находите у разбитой телеги тайник с золотом и видите, что следы всех четырёх свидетелей здесь действительно сходятся.","f":"На месте исчезнувшего каравана вас встречают вооружённые люди, скрывавшиеся среди деревьев. Начинается битва."},"E300.2":{"s":"Вы оплачиваете четырём путникам их рассказы и получаете припасы, которые они сохранили после ночи. Истории остаются несовместимыми."},"E300.3":{"s":"{{heroName}} сопоставляет четыре версии и находит место, где каждая описывает отдельную часть нападения. У телеги отряд получает золото и припасы.","f":"{{heroName}} обнаруживает, что у каждого свидетеля верная деталь, но общий ход событий восстановить нельзя. Виновный остаётся неизвестен."},"E300.4":{"s":"Вы оставляете четверых спорить о караване без тел. Последняя версия скелета звучит уже на рассвете."},"E301.1":{"s":"Вы заставляете совет объявить Орлена живым перед всем городом. За исправленную ошибку капитан благодарит золотом, а оркестр играет уже другую мелодию.","f":"Совет отказывается переносить оплаченные похороны и предлагает Орлену подождать их окончания. Признания не происходит."},"E301.2":{"s":"Орлен решает, что новому живому человеку найдётся дело в королевском походе. Он присоединяется к отряду.","f":"Капитан не желает покидать город, где у него уже поставили памятник. Вступить в отряд он отказывается.","v":{"rs":"Орлен согласен уйти с Королём, но свободного места нет. Капитан благодарит золотом за предложенный выход."}},"E301.3":{"s":"{{heroName}} убеждает совет оставить памятник как знак победы, а не смерти Орлена. Город платит золотом за сохранённый бюджет и живого капитана.","f":"{{heroName}} не может примирить совет с очевидным фактом возвращения Орлена. За затянувшееся разбирательство взыскивают золото."},"E301.4":{"s":"Вы оставляете Орлена спорить с собственным памятником. На площади уже репетируют речь о безвременно погибшем капитане."},"E302.1":{"s":"Вы защищаете Нерса, пока он сверяет печати и выдаёт письма настоящим адресатам. Почтальон благодарит золотом за сохранённую почту.","f":"Один из нетерпеливых мужчин хватает мешок, а остальные выхватывают оружие. Начинается стычка."},"E302.2":{"s":"Вы покупаете у Нерса дорожные припасы, оставленные для почтового пути. Он просит не трогать чёрный конверт."},"E302.3":{"s":"{{heroName}} укрепляет ось и возвращает колесо на место. Нерс благодарит золотом и припасами за возможность завершить доставку.","f":"При подъёме повозки ломается домкрат, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Колесо срывается при ремонте, но никто из допустимых бойцов не получает тяжёлого ранения. Почтовый рейс не возобновлён."}},"E302.4":{"s":"Вы оставляете Нерса сортировать письма под взглядами трёх подозрительных получателей. Чёрная печать остаётся целой."},"E303.1":{"s":"Марта сама называет того, с кем хочет идти дальше, и мужчины наконец слышат решение не от Короля. Семья благодарит припасами за возвращённое право выбора.","f":"Марта просит отложить свадьбу, пока оба жениха перестанут спорить, но ни один не слушает. Праздник останавливается."},"E303.2":{"s":"Вы убеждаете обоих мужчин не превращать возвращение с войны в дуэль. Священник благодарит золотом за сохранённый мир.","f":"Оба жениха объявляют себя оскорблёнными и зовут сторонников. Начинается стычка."},"E303.3":{"s":"{{heroName}} отказывается начинать церемонию, пока Марта не даст свободного согласия. За защиту её решения семья выплачивает золото.","f":"{{heroName}} не получает ясного согласия Марты и откладывает обряд. Праздничная процессия остаётся на дороге."},"E303.4":{"s":"Вы объезжаете свадьбу, на которой никто не спросил невесту, чего она хочет. Элд возвращает церемониальную книгу под мышку."},"E304.1":{"s":"Вы оплачиваете штраф и позволяете Дорасу замешивать тесто ночью. К утру он выдаёт отряду свежий хлеб и припасы."},"E304.2":{"s":"Вы добиваетесь исключения для пекарни, и ночные печи снова работают. Благодарные горожане делятся припасами.","f":"Стража требует строго соблюдать указ и не даёт открыть печи. Спор переходит в стычку."},"E304.3":{"s":"{{heroName}} организует тихую ночную смену без грохота противней. Дорас печёт хлеб и снабжает отряд припасами.","f":"Одна из печей всё же гремит среди ночи, и стража конфискует часть приготовленных запасов. Припасов становится меньше."},"E304.4":{"s":"Вы уходите до начала тихого хлебного бунта. За воротами горожане показывают стражникам весьма красноречивые жесты."},"E305.1":{"s":"Вы показываете покупателям три несовместимых размера сапог, и Фесс не находит ответа. За прекращённый обман пристав выдаёт золото.","f":"Фесс объявляет третий сапог церемониальным, а покупатели верят ему на слово. Разоблачить торговца не удаётся."},"E305.2":{"s":"Вы покупаете припасы у соседних лавок, пока вся площадь спорит о размерах ног Астена. Продавцы рады хоть обычной сделке."},"E305.3":{"s":"{{heroName}} обнаруживает три печати разных мастерских на одном «королевском» комплекте. Фесс возвращает золото за подделки.","f":"{{heroName}} не может опровергнуть все свидетельства сразу, а торговец взыскивает плату за экспертизу. Отряд теряет золото."},"E305.4":{"s":"Вы позволяете рынку спорить о трёх сапогах одного короля. Фесс уже предлагает четвёртый — «для торжественных случаев»."},"E306.1":{"s":"Вы отбираете у человека в сером плаще записанные чужие признания и находите у него золото за шантаж.","f":"Серый незнакомец свистит своим помощникам, и те бросаются спасать записи. Начинается стычка."},"E306.2":{"s":"Вы предупреждаете очередь, и люди прекращают исповедоваться на весь двор. Благодарный Олм оставляет отряду припасы.","f":"Священник не верит, что стены выдают чужие слова, и продолжает службу. Очередь остаётся подслушиваемой."},"E306.3":{"s":"{{heroName}} находит в стенах зачарованные вставки, которые усиливают шёпот. Олм благодарит золотом и припасами за восстановленную тайну исповеди.","f":"Одна из вставок отзывается магическим ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Зачарованная стена отталкивает исследователей, но никто из допустимых бойцов не получает тяжёлого ранения. Исповеди по-прежнему слышны снаружи."}},"E306.4":{"s":"Вы проходите мимо часовни, не задерживаясь у чужих исповедей. Человек в сером плаще продолжает быстро писать."},"E307.1":{"s":"Вы помогаете эльфам завершить прощание с дубом, и хранительница Маэль делится припасами. Тиван убирает пилу до окончания обряда.","f":"Эльфы не могут согласиться, нужно ли хоронить дерево или дать ему новое назначение. Обряд не заканчивается."},"E307.2":{"s":"Вы убеждаете Тивана не трогать ствол, пока Маэль не решит вопрос с хранителями. Лесоруб платит золотом за достигнутую отсрочку.","f":"Тиван боится упустить древесину для моста и отказывается ждать. Спор с эльфами продолжается."},"E307.3":{"s":"{{heroName}} обнаруживает, что корни дуба уже отмерли, а древесина пригодна для моста без вреда соседним деревьям. Маэль благодарит золотом и припасами.","f":"Попытка проверить внутренние кольца приводит к удару живого корня, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Оставшиеся корни отталкивают исследователей, но никто из допустимых бойцов не получает тяжёлого ранения. Заключение о дубе не готово."}},"E307.4":{"s":"Вы не вмешиваетесь в прощание с девятисотлетним дубом. Тиван ждёт рядом с пилой, но к стволу не подходит."},"E308.1":{"s":"Вы помогаете загнать невидимого оленя к охотникам и возвращаете украденные запасы еды. Отряду достаются припасы.","f":"Невидимый зверь прорывается сквозь загон, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Невидимый олень сбивает загон, но никто из допустимых бойцов не получает тяжёлого ранения. Сушёные яблоки остаются у него."}},"E308.2":{"s":"Вы оставляете приманку для невидимого оленя и платите охотникам за их запасы. Вейра просит держать мешки завязанными."},"E308.3":{"s":"{{heroName}} читает следы в снегу и находит логово с украденными вещами и золотом. Охотники благодарят за разгадку.","f":"В заснеженном лесу {{affectedHeroName}} получает тяжёлое ранение от внезапного удара невидимого зверя.","v":{"nf":"Невидимый зверь срывает преследование, но никто из допустимых бойцов не получает тяжёлого ранения. Следы снова обрываются."}},"E308.4":{"s":"Вы оставляете невидимому оленю его победу над охотниками и яблоками. Вейра завязывает мешки двойными узлами."},"E309.1":{"s":"Ночью из леса звучит недостающая нота, и Лиор наконец осмеливается ответить. В старом схроне у моста находится золото.","f":"На звук музыки из леса выходят вооружённые чужаки, не имеющие отношения к памяти жены. Начинается стычка."},"E309.2":{"s":"Вы платите Лиору за указание безопасной лесной тропы. Он провожает отряд тихой мелодией без последнего звука."},"E309.3":{"s":"{{heroName}} определяет, что ответ приходит из старого акустического прохода за мостом. Лиор благодарит золотом и припасами за найденную причину.","f":"Попытка приблизиться к источнику звука заканчивается опасным ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Скрытый источник звука отталкивает разведчиков, но никто из допустимых бойцов не получает тяжёлого ранения. Последняя нота остаётся загадкой."}},"E309.4":{"s":"Вы оставляете Лиора на мосту с незаконченной мелодией. Он впервые за день не пытается доиграть её до конца."},"E310.1":{"s":"Вы оплачиваете садовнику ущерб от украденного винограда и отпускаете рыжую лису. Элвар записывает дело как закрытое без признания подсудимой."},"E310.2":{"s":"Вы отдаёте припасы в возмещение семи гроздей винограда, и Рин смиряется с потерей. Он выдаёт золото за урегулированный спор."},"E310.3":{"s":"{{heroName}} показывает, что понятие презрения к ограде нельзя доказать показаниями лисы. Суд закрывает дело и благодарит золотом.","f":"{{heroName}} не может убедить Элвара снять обвинение в систематическом нарушении границ. Лиса зевает ещё громче."},"E310.4":{"s":"Вы оставляете эльфийский суд решать, что думает лиса о его юрисдикции. Обвиняемая спокойно вылизывает вторую лапу."},"E311.1":{"s":"Вы ориентируетесь по камину и находите обоих гостей в комнате, которая успела побывать кухней. Ивэль платит золотом за возвращённых постояльцев.","f":"Дом переставляет стены за спиной, и {{affectedHeroName}} получает тяжёлое ранение при обрушении прохода.","v":{"nf":"Комнаты смыкаются вокруг поисковой группы, но никто из допустимых бойцов не получает тяжёлого ранения. Гостей пока не находят."}},"E311.2":{"s":"Вы покупаете у Ивэль дорожные припасы, не заходя за порог. Хозяйка просит дать знать, если где-нибудь встретится её гостиная."},"E311.3":{"s":"{{heroName}} находит неподвижные несущие стены среди меняющихся комнат и выводит гостей наружу. Ивэль благодарит золотом и припасами.","f":"Перекрытие сдвигается прежде, чем {{heroName}} успевает закрепить его, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Перекрытие падает, но никто из допустимых бойцов не получает тяжёлого ранения. Дом не отдаёт пропавших гостей."}},"E311.4":{"s":"Вы оставляете Ивэль у дома, которому не нравится собственная планировка. За её спиной дверной проём становится окном."},"E312.1":{"s":"Вы успеваете разобрать строки из сухих листьев, и Тейла показывает по ним схрон с припасами.","f":"Листья взвиваются вихрем и наносят {{affectedHeroName}} тяжёлое ранение.","v":{"nf":"Вихрь разметает листья, но никто из допустимых бойцов не получает тяжёлого ранения. Прочесть письмо не удаётся."}},"E312.2":{"s":"Вы передаёте Тейле припасы для общины, и она благодарит золотом. Листья у дороги перестают складываться в строки на время прощания."},"E312.3":{"s":"{{heroName}} отмечает повторяющиеся знаки и восстанавливает смысл письма. Арас платит золотом за прочитанное послание.","f":"{{heroName}} не может собрать последнюю строку: листья рассыпаются при каждом новом порыве. Адресат остаётся неизвестен."},"E312.4":{"s":"Вы не отвечаете посланию, которое само выбирает читателя. Последняя строка распадается, едва отряд уходит."},"E313.1":{"s":"Грум терпит достойное поражение, сохранив нос для свадебного портрета. Хага вручает золото за отлично проведённый поединок.","f":"Один удар выходит сильнее задуманного, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Поединок заканчивается опасным столкновением, но никто из допустимых бойцов не получает тяжёлого ранения. Хага не признаёт поражение достойным."}},"E313.2":{"s":"Вы вручаете семье припасы вместо поединка, и Хага благодарит золотом за заботу о свадьбе. Грум всё ещё ищет подходящего соперника."},"E313.3":{"s":"{{heroName}} устраивает показательный бой, в котором Грум проигрывает красиво, а его нос остаётся цел. Хага платит золотом.","f":"На резком повороте {{affectedHeroName}} получает тяжёлое ранение, и показательный поединок приходится прервать.","v":{"nf":"Показательный бой останавливают после опасного удара, но никто из допустимых бойцов не получает тяжёлого ранения. Хага остаётся недовольна."}},"E313.4":{"s":"Вы желаете Груму удачной свадьбы и оставляете Хагу оценивать других противников. Орк обещает постараться проиграть достойно."},"E314.1":{"s":"Вы делите суп между обоими кланами, и Бург впервые может спокойно разливать его половником. За помощь отряду достаются припасы.","f":"Вожди требуют сначала решить, кому принадлежит котёл, и отказываются даже пробовать суп. Ужин остывает."},"E314.2":{"s":"Вы оплачиваете медный котёл и забираете право распоряжаться ужином. Бург с облегчением выдаёт припасы, чтобы закончить спор."},"E314.3":{"s":"{{heroName}} находит под ручкой старое клеймо кузнеца, а Бург подтверждает, кому был сделан заказ. Кланы благодарят золотом за развязку.","f":"{{heroName}} обнаруживает два клейма разных мастеров, и спор переходит к происхождению каждой ручки. Решение откладывается."},"E314.4":{"s":"Вы уходите, пока два орочьих отряда строятся из-за холодеющего супа. Бург обещает половником остановить любую битву."},"E315.1":{"s":"Вы снимаете с полотнища броскую кайму, и знамя больше не выделяется издалека как мишень. Урк благодарит золотом за сохранённую реликвию.","f":"Мада считает переделку недостаточной и по-прежнему требует сжечь знамя. Отряд уходит без награды."},"E315.2":{"s":"Вы покупаете у орочьего лагеря припасы, не приближаясь к спорному знамени. Урк раздумывает, кто понесёт его завтра."},"E315.3":{"s":"{{heroName}} проверяет полотнище и находит обычную сигнальную краску вместо проклятия. За объяснение Мада отдаёт золото.","f":"Из складок знамени вырывается защитная вспышка, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Знамя опасно вспыхивает при проверке, но никто из допустимых бойцов не получает тяжёлого ранения. Причина не раскрыта."}},"E315.4":{"s":"Вы оставляете оркам знамя, чья заметность давно стала легендой. Урк отодвигает его ещё дальше от костра."},"E316.1":{"s":"Вы догоняете подростков у ручья и возвращаете Могу украденный барабан. Клан благодарит золотом за отсутствие карательного похода.","f":"Подростки зовут вооружённых старших братьев и отказываются вернуть инструмент. Начинается стычка."},"E316.2":{"s":"Вы убеждаете Сара заменить карательный поход уроком музыки для обоих кланов. Мог выдаёт припасы в благодарность.","f":"Сар требует примерного наказания и не желает слушать о детских шалостях. Войско продолжает собираться."},"E316.3":{"s":"{{heroName}} перехватывает подростков на развилке, прежде чем они успевают испортить барабан. Сар выплачивает золото.","f":"На перегоне {{affectedHeroName}} получает тяжёлое ранение, когда похитители пытаются уйти через опасное ущелье.","v":{"nf":"Перехват срывается на опасном спуске, но никто из допустимых бойцов не получает тяжёлого ранения. Барабан не возвращён."}},"E316.4":{"s":"Вы оставляете Сара слушать пропущенный четвёртый удар издалека. Мог прикрывает лицо рукой от позора ритма."},"E317.1":{"s":"Вы убеждаете Геха вернуться к родным, обещая переговорить о семейных требованиях. Клан платит золотом за его освобождение.","f":"Гех отказывается менять трёхразовое питание на семейные долги. Торр не знает, радоваться ли такому пленнику."},"E317.2":{"s":"Гех решает, что в королевском отряде можно есть кашу и не слушать родственников. Он присоединяется к походу.","f":"Гех спрашивает о расписании приёмов пищи и, услышав ответ, предпочитает клетку. Нанять его не удаётся.","v":{"rs":"Гех согласен уйти из клетки, но нового бойца принять нельзя. Родственники выплачивают отряду золото за попытку."}},"E317.3":{"s":"{{heroName}} договаривается, чтобы Гех вернулся домой без прежних долгов и с условием кормить его вовремя. Клан благодарит золотом.","f":"{{heroName}} не может примирить родственников с требованиями Геха, и Торр взыскивает плату за затянувшееся содержание. Казна теряет золото."},"E317.4":{"s":"Вы оставляете Геха наслаждаться кашей в клетке, а Торра — думать, как выгнать довольного пленника. Клан всё ещё ждёт снаружи."},"E318.1":{"s":"Вы выдерживаете один удар Краха и проходите через мост без ответного удара. Кузнец Оба записывает ещё одну выполненную традицию.","f":"Дубина обрушивается слишком тяжело, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Удар приходится в защиту, но никто из допустимых бойцов не получает тяжёлого ранения. Крах требует повторить испытание."}},"E318.2":{"s":"Вы платите Краху за день без ударов и проходите мост, пока он с удивлением разглядывает полученное золото."},"E318.3":{"s":"{{heroName}} принимает удар на крепкую защиту и получает право провести отряд. Крах благодарит золотом за достойное испытание.","f":"Дубина пробивает стойку, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Удар не приводит к тяжёлому ранению допустимого бойца, но Крах объявляет испытание не пройденным. Награды нет."}},"E318.4":{"s":"Вы тратите припасы на другую переправу, не испытывая чужую дубину на собственной голове. Оба наблюдает за уходящими с явным одобрением."},"E319.1":{"s":"Вы находите в старой кладбищенской книге имя, подходящее к воспоминаниям скелета. Тот благодарит золотом за возвращённое прошлое.","f":"Весс обнаруживает несколько одинаковых записей и не может определить нужную. Скелет отказывается называться наугад."},"E319.2":{"s":"Вы отдаёте скелету припасы для пути к прежнему дому, а тот делится золотом, оставшимся при нём после смерти."},"E319.3":{"s":"{{heroName}} восстанавливает стёртые буквы на надгробии, и скелет наконец читает собственное имя. Весс благодарит золотом.","f":"Старая плита отвечает магическим ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Надгробие срабатывает защитной печатью, но никто из допустимых бойцов не получает тяжёлого ранения. Имя остаётся забытым."}},"E319.4":{"s":"Вы предлагаете скелету выбрать новое имя, не дожидаясь решения старых записей. Он задумчиво смотрит на пустую плиту."},"E320.1":{"s":"Вы помогаете деревне завершить старые похоронные слова, и оркестр наконец умолкает. Благодарные жители выдают припасы.","f":"Дирижёр не может вспомнить последний куплет, и музыканты опять начинают марш. Обряд не закончен."},"E320.2":{"s":"Вы платите жителям за сведения о покойном хозяине оркестра. Пелл внимательно слушает, не прекращая дирижировать."},"E320.3":{"s":"{{heroName}} восстанавливает недостающий конец церемонии, и оркестр завершает шестидневное выступление. Пелл благодарит золотом и припасами.","f":"Обряд вызывает опасный отклик старой магии, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Поминальная магия срывает исполнение, но никто из допустимых бойцов не получает тяжёлого ранения. Оркестр продолжает марш."}},"E320.4":{"s":"Вы покидаете деревню до следующего куплета. Пелл, не имея лёгких, всё равно вздыхает перед новым вступлением."},"E321.1":{"s":"Вы признаёте буквальное исполнение завещания Вальтера и передаёте дом детям. Покойный благодарит золотом за возможность больше не быть владельцем.","f":"Нотариус считает возвращение Вальтера юридическим препятствием и не оформляет передачу. Семья продолжает спорить за чужую выгоду."},"E321.2":{"s":"Вы оплачиваете Сию независимое разбирательство, и нотариус наконец получает время перечитать завещание. Вальтер терпеливо ждёт."},"E321.3":{"s":"{{heroName}} доказывает, что условие «после моей смерти» однажды уже наступило и не отменяется воскресением. Вальтер благодарит золотом.","f":"{{heroName}} не находит бесспорного толкования, а нотариус взыскивает пошлину. Отряд теряет золото."},"E321.4":{"s":"Вы оставляете детей отказываться от имущества в пользу покойного отца. Нотариус трет виски над очевидно подлинным завещанием."},"E322.1":{"s":"Вы находите искателей за внутренней дверью и забираете золотой кошель, пока башня не дошла до сотни.","f":"Счёт достигает критической отметки, и из стен выступают вооружённые хранители. Начинается битва."},"E322.2":{"s":"Вы быстро подбираете оставленные вещи у порога и забираете припасы, не добавив башне новых шагов.","f":"При попытке унести сумки в проёме появляются вооружённые стражи счётной башни. Начинается стычка."},"E322.3":{"s":"{{heroName}} рассчитывает кратчайший путь до оставленных вещей и извлекает золото без лишних шагов.","f":"Стены резко сдвигаются при подсчёте маршрута, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Башня меняет проход до сотого шага, но никто из допустимых бойцов не получает тяжёлого ранения. Тайник не достигнут."}},"E322.4":{"s":"Вы обходите башню, не помогая ей досчитать до ста. За спиной шёпот останавливается на следующем числе."},"E323.1":{"s":"Вы подтверждаете право Арка купить семейную корону независимо от наличия головы. Торговец платит золотом за королевское разъяснение.","f":"Торговец отказывается продавать украшение, которое некуда надеть. Арк требует письменного отказа."},"E323.2":{"s":"Вы покупаете у торговца припасы, пока Арк и оруженосец обсуждают наплечники. Корона по-прежнему лежит на прилавке."},"E323.3":{"s":"{{heroName}} предлагает Арку носить корону как знак на знамени, а не на отсутствующей голове. Оруженосец доволен, торговец платит золотом.","f":"{{heroName}} предлагает несколько вариантов крепления, но Арк отвергает каждый как недостойный рода. Сделка не совершается."},"E323.4":{"s":"Вы не берётесь судить безголовую геральдику. Арк требует принести ему родословную вместе с чертежами короны."},"E324.1":{"s":"Вы трижды стучите по крышке, и голос из могилы удовлетворённо отвечает: «Снаружи на месте». Руф находит у камня оставленный золотой кошель.","f":"После третьего удара из земли поднимаются вооружённые стражи могилы. Начинается стычка."},"E324.2":{"s":"Вы платите Руфу за рассказ о вчерашних похоронах, и тот проводит отряд к записи умершего. Голос из земли продолжает ждать трёх стуков."},"E324.3":{"s":"{{heroName}} проверяет надгробие и находит вентиляционный канал, по которому проходит голос. Руф благодарит припасами за спокойствие.","f":"Земля оседает под ногами {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Могила опасно оседает, но никто из допустимых бойцов не получает тяжёлого ранения. Источник голоса остаётся неизвестен."}},"E324.4":{"s":"Вы не отвечаете голосу, которому важно проверить внешнюю сторону крышки. Руф остаётся возле могилы с поднятой рукой."},"E325.1":{"s":"Вы платите Шасс за проход по паутине и получаете аккуратную квитанцию. Паук подтягивает оборвавшуюся нить под вашими ногами."},"E325.2":{"s":"Вы разрезаете край паутины и возвращаете каравану старую дорогу без пошлины.","f":"Паук зовёт своих вооружённых защитников, когда вы режете построенный им мост. Начинается стычка."},"E325.3":{"s":"{{heroName}} обнаруживает, что сеть перекрыла общую дорогу, а значит, плата не согласована владельцами тракта. Шасс возвращает золото.","f":"{{heroName}} не находит точной записи о праве проезда, а Шасс взыскивает плату за рассмотрение спора. Отряд теряет золото."},"E325.4":{"s":"Вы расходуете припасы на обход каньона, не оплачивая паучий мост. Шасс уже выписывает квитанцию следующему каравану."},"E326.1":{"s":"Вы подтверждаете претензию Вирры: один свидетель и двенадцать — разные условия заказа. Гильдия возвращает золото за спор.","f":"Заказчик зовёт своих телохранителей, считая решение нарушением контракта. Начинается стычка."},"E326.2":{"s":"Вы оплачиваете секретарю безопасный проход через земли гильдии. Гусь провожает отряд крайне недружелюбным шипением."},"E326.3":{"s":"{{heroName}} обнаруживает, что контракт не уточняет число свидетелей и вообще не определяет права гуся. Гильдия платит золото за юридическую ясность.","f":"{{heroName}} не может доказать, что гусь был свидетелем, а секретарь взыскивает судебные расходы. Отряд теряет золото."},"E326.4":{"s":"Вы уходите до появления тринадцатого свидетеля, пока Вирра спорит с заказчиком. Гусь занимает её место за столом."},"E327.1":{"s":"На балконе вы находите золотой кошель в кармане чужих перчаток. Нарва уверяет, что кресла никогда не покупала.","f":"Балкон перемещается к соседнему окну во время осмотра, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Балкон неожиданно сдвигается, но никто из допустимых бойцов не получает тяжёлого ранения. Чужие вещи остаются наверху."}},"E327.2":{"s":"Вы покупаете у Нарвы дорожные припасы и уходите, не трогая странный балкон. Селисс уже готовит новые чертежи дома."},"E327.3":{"s":"{{heroName}} находит крепёж, уходящий не в стену, а в старую кладку соседнего здания. За разгадку Нарва благодарит золотом.","f":"Одна из скрытых опор балкона ломается, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Опора обрушивается, но никто из допустимых бойцов не получает тяжёлого ранения. Причина появления балкона не найдена."}},"E327.4":{"s":"Вы оставляете Нарву у балкона без двери. На кресле уже лежат новые перчатки, хотя никто не поднимался наверх."},"E328.1":{"s":"Вы убеждаете Ильзару принять остаток золота и позволить Тарену уйти без семейной интриги. Сын благодарит золотом за свободу.","f":"Ильзара считает простую отдачу денег слишком бесхитростной и требует от сына хотя бы придумать заговор. Переговоры срываются."},"E328.2":{"s":"Тарен выбирает поход, где правду можно говорить без семейных скандалов. Он присоединяется к отряду.","f":"Тарен отказывается вступать в новый отряд, пока мать не прекратит искать за ним интригу. Нанять его не удаётся.","v":{"rs":"Тарен готов вступить в отряд, но свободного места нет. Он благодарит золотом за предложенный выход."}},"E328.3":{"s":"{{heroName}} убеждает Ильзару признать прямой разговор новой формой семейного искусства. За мирный отъезд Тарена матриарх платит золотом.","f":"Ильзара объявляет переговоры бесчестной попыткой обойти традиции, и её охрана вступает в стычку."},"E328.4":{"s":"Вы оставляете Ильзару и Тарена выяснять, насколько честность прилична для их рода. Сын снова показывает, где лежит остаток денег."},"E329.1":{"s":"Вы задаёте вопрос Фаэлу, а кристалл выдаёт ответ ещё до его рта и открывает золотую закладку у стола.","f":"Камень произносит запретную фразу и наносит {{affectedHeroName}} тяжёлое ранение.","v":{"nf":"Кристалл вспыхивает на преждевременном ответе, но никто из допустимых бойцов не получает тяжёлого ранения. Допрос прерывается."}},"E329.2":{"s":"Вы платите дознавателю за сведения и уходите, не дожидаясь следующего предсказанного ответа. Камень шепчет что-то вслед."},"E329.3":{"s":"{{heroName}} определяет, что кристалл повторяет не ложь, а намерение солгать до слов. Дознаватель благодарит золотом и припасами.","f":"Камень оборачивается к исследователю резким ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Кристалл срывает исследование опасной вспышкой, но никто из допустимых бойцов не получает тяжёлого ранения. Его устройство остаётся тайной."}},"E329.4":{"s":"Вы прекращаете разговор, в котором предмет говорит раньше собеседника. Фаэл впервые выглядит благодарным за молчание."},"E330.1":{"s":"Вы проводите обоих пауков через мост, не позволив им сцепиться лапами. Реллис и Саар благодарят золотом за сохранённую свадьбу.","f":"Пауки сталкиваются на середине моста, а их хозяева зовут помощников на драку. Начинается стычка."},"E330.2":{"s":"Вы дарите молодожёнам припасы и оставляете их искать способ провести церемонию. Жрица благодарит золотом за поддержку."},"E330.3":{"s":"{{heroName}} успокаивает пауков и проводит одного за другим, не требуя от зверей свадебного строя. Жрица награждает золотом.","f":"Один из пауков резко бросается через мост, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Пауки срывают порядок шествия, но никто из допустимых бойцов не получает тяжёлого ранения. Свадьба задерживается."}},"E330.4":{"s":"Вы оставляете Реллис и Саара перед двумя неподвижными пауками. Жрица уже предлагает провести свадьбу по обе стороны моста."},"E331.1":{"s":"Вы платите за место почти у горна и проходите мимо возмущённых шахтёров. Бела ставит ваше имя в список без лишних вопросов."},"E331.2":{"s":"Вы убеждаете кузнечную очередь не покупать чужое время, и предприимчивому дварфу приходится вернуть часть золота. Отряд получает свою долю.","f":"Шахтёры считают торговлю местами удобной и не хотят от неё отказываться. Бела продолжает злиться за кассой."},"E331.3":{"s":"{{heroName}} договаривается с Гормом о приоритете срочного походного ремонта. Мастер возвращает золото за освобождённое место.","f":"{{heroName}} не может убедить Горма пропустить отряд без доплаты, и за переговоры взимают золото."},"E331.4":{"s":"Вы проходите мимо кузницы, где торгуют ожиданием. На дороге уже предлагают место в очереди к самому продавцу очереди."},"E332.1":{"s":"Вы вытягиваете подъёмную клеть до верхнего уровня, и трое шахтёров отдают золото за спасение. Трум наконец перестаёт обвинять тормоза.","f":"Канат резко дёргается, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Клеть опасно дёргается, но никто из допустимых бойцов не получает тяжёлого ранения. Шахтёры остаются между уровнями."}},"E332.2":{"s":"Вы платите Труму за шахтёрские припасы и уходите, не дожидаясь возобновления работы лифта. Снизу уже называют цену экскурсии."},"E332.3":{"s":"{{heroName}} находит зажатую собачку тормоза и возвращает клети ход. Благодарные шахтёры платят золотом.","f":"Подъёмный механизм резко сжимается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Механизм срывает ремонт, но никто из допустимых бойцов не получает тяжёлого ранения. Клеть остаётся неподвижной."}},"E332.4":{"s":"Вы оставляете Трума разбираться с лифтом, который отрицает законы механики. Из шахты доносится требование принести завтрак."},"E333.1":{"s":"Вы заявляете совету, что хорошее пиво не обязано причинять страдания. Хольд благодарит золотом за защиту рецепта.","f":"Дегустаторы отказываются признавать напиток достойным традиции, потому что никто не поморщился. Суд продолжается."},"E333.2":{"s":"Вы покупаете у Хольда дорожную провизию, пока совет решает судьбу его пива. Пивовар рад хоть одной сделке без дегустации."},"E333.3":{"s":"{{heroName}} расспрашивает работников и выясняет, что рецепт давно улучшали вместе, не пытаясь обмануть традицию. Хольд платит золотом за свидетельство.","f":"Работники боятся ссориться с советом и не дают показаний о рецепте. {{heroName}} возвращается ни с чем."},"E333.4":{"s":"Вы оставляете дварфам право страдать от вкусного пива. Судья внимательно ждёт, когда хотя бы один посетитель поморщится."},"E334.1":{"s":"Вы вежливо извиняетесь перед сейфом от имени Фарна, и замок наконец щёлкает. Казначей благодарит золотом за спасённую кассу.","f":"Сейф отвечает новой надписью «НЕДОСТАТОЧНО ИСКРЕННЕ» и остаётся закрытым."},"E334.2":{"s":"Вы платите Дорри за припасы и оставляете Фарна извиняться перед сейфом. Ключи лежат в замке, как и прежде."},"E334.3":{"s":"{{heroName}} разбирает рунный механизм, не задев охранные печати, и открывает городской сейф. Фарн выплачивает золото.","f":"Обиженный замок защёлкивает металлическую шторку, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Замок резко захлопывается, но никто из допустимых бойцов не получает тяжёлого ранения. Сейф продолжает требовать вежливости."}},"E334.4":{"s":"Вы желаете сейфу хорошего дня и уходите. На замочной пластине появляется короткое «ВЗАИМНО»."},"E335.1":{"s":"Вы дожидаетесь, пока Кеда первой закончит последний удар по гвоздю. Олт платит золотом за терпеливое судейство.","f":"Соревнование затягивается до ночи, а кузнецы даже не приблизились к завершению. Награды зрителям не предусмотрено."},"E335.2":{"s":"Вы покупаете у зрителей припасы, пока они часами следят за одним гвоздём. Никто не отрывает глаз от молотка."},"E335.3":{"s":"{{heroName}} замечает, что Брун улучшает структуру металла каждым редким ударом. Судья Олт платит золотом за техническое заключение.","f":"{{heroName}} не может определить разницу между двумя почти одинаковыми гвоздями. Состязание продолжается."},"E335.4":{"s":"Вы уходите прежде, чем девятичасовой гвоздь объявят священной реликвией. Толпа замирает перед очередным ударом."},"E336.1":{"s":"Вы идёте по отметкам Керна и находите гору там, где карта показывала пустую степь. Найденная руда приносит золото.","f":"Вместо рудной жилы путешественники находят укреплённую стоянку вооружённых чужаков. Начинается битва."},"E336.2":{"s":"Вы выкупаете у Керна настоящий тяжёлый образец руды, не пытаясь найти исчезнувшую гору. Мири проверяет его вес ещё раз."},"E336.3":{"s":"{{heroName}} прослеживает первые ориентиры и находит спрятанный запас руды с золотом и припасами.","f":"На необозначенном склоне {{affectedHeroName}} получает тяжёлое ранение от камнепада.","v":{"nf":"Неизвестный склон осыпается, но никто из допустимых бойцов не получает тяжёлого ранения. Маршрут приходится прервать."}},"E336.4":{"s":"Вы не ищете гору, которая отказывается стоять на карте. Керн складывает образец в сумку и снова изучает пустую степь."},"E337.1":{"s":"Вы покупаете у Кезза припасы, внимательно выслушав все их недостатки. Демон удивлённо выдаёт товар без единого скрытого условия."},"E337.2":{"s":"Вы помогаете Кеззу объяснить покупателям, что честное предупреждение не является новой ловушкой. Демон выплачивает золото за спасённый торг.","f":"Клиенты принимают ваше участие за рекламу и требуют возмещения за подозрительный совет. Отряд теряет золото."},"E337.3":{"s":"{{heroName}} проверяет сделки и подтверждает: Кезз действительно говорит правду о каждом товаре. Благодарный демон платит золотом.","f":"{{heroName}} обнаруживает, что предупреждения слишком расплывчаты для полного одобрения. Сделки остаются под подозрением."},"E337.4":{"s":"Вы благодарите Кезза за честный день и уходите без покупки. Демон с тоской глядит на товар, который так и не смог продать."},"E338.1":{"s":"Вы находите владельца талона 666 за последним рядом, и очередь наконец движется дальше. Нак платит золотом за устранённую задержку.","f":"Владелец талона зовёт помощников, опасаясь немедленной расплаты за номер. Начинается стычка."},"E338.2":{"s":"Вы платите Наку за проход мимо застрявшей очереди. Демоны продолжают молчать при объявлении номера 666."},"E338.3":{"s":"{{heroName}} сверяет выданные талоны и находит того, кто спрятал свой номер под одеждой. Нак благодарит золотом.","f":"{{heroName}} узнаёт, что талон несколько раз перепродавали, и след владельца теряется. Очередь не сдвигается."},"E338.4":{"s":"Вы обходите чёрную арку стороной. Издали ещё слышится голос регистратора: «Номер шестьсот шестьдесят шесть!»"},"E339.1":{"s":"Вы помогаете Раху держать фонари горящими до рассвета, и багровое пламя успокаивается. Угольщик благодарит золотом.","f":"Ночью из темноты выходят вооружённые существа, тянущиеся к испуганному огню. Начинается стычка."},"E339.2":{"s":"Вы отдаёте Раху припасы для ночного перехода, и он платит золотом за помощь своему странному огню."},"E339.3":{"s":"{{heroName}} обнаруживает, что пламя боится не ночи, а скрытого в ней холодного излучения. Рах благодарит золотом за находку.","f":"Попытка проверить свойства огня оборачивается вспышкой, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Пламя вспыхивает опасно, но никто из допустимых бойцов не получает тяжёлого ранения. Причина страха остаётся неизвестной."}},"E339.4":{"s":"Вы не выясняете, чего боится демоническое пламя. Рах снова поднимает фонарь повыше, чтобы оно не исчезло."},"E340.1":{"s":"Вы объявляете начало минуты свидетелем, и песочные часы наконец переворачиваются. Азрел платит золотом за оформленный отсчёт.","f":"Демон объявляет решение нарушением условий и зовёт вооружённых посредников. Начинается стычка."},"E340.2":{"s":"Вы отдаёте Азрелу золото за освобождение Лорна от минуты, которая никак не начиналась. Песок в часах наконец оседает."},"E340.3":{"s":"{{heroName}} находит юридическую границу: без начала отсчёта нет и исполнения сделки. Азрел возвращает золото за прекращённый договор.","f":"{{heroName}} не может убедить стороны, и Азрел взыскивает золото за судебную проверку. Часы всё ещё стоят."},"E340.4":{"s":"Вы оставляете Лорна с Азрелом спорить о минуте, которая длится пятый час. Песок по-прежнему не падает."},"E341.1":{"s":"Вы помогаете Тику собрать три искренних извинения без печатей и присяг. Бес платит золотом за восстановленное достоинство.","f":"Тик отвергает каждое извинение как недостаточно искреннее и продолжает составлять список должников."},"E341.2":{"s":"Вы покупаете у хозяйки трактира припасы, пока Тик демонстрирует свой список обид. Она просит не занимать его стул."},"E341.3":{"s":"{{heroName}} объясняет должникам, чего Тик ждёт на самом деле, и приводит их к простому разговору. Бес платит золотом за посредничество.","f":"Один из должников считает требования Тика вымогательством и зовёт приятелей. Начинается стычка."},"E341.4":{"s":"Вы заранее извиняетесь перед Тиком за всё, что могли бы сделать, и уходите. Бес долго ищет в списке подходящую графу."},"E342.1":{"s":"Вы находите ошибку между участками 18 и 81 и заставляете привратника вернуть адскую дверь в назначенное место. Мален благодарит золотом.","f":"Демон отказывается покинуть утверждённый адрес и вызывает вооружённых стражей портала. Начинается битва."},"E342.2":{"s":"Вы покупаете у Зоры дорожные припасы прежде, чем жар из портала испортит оставшиеся продукты. Повариха немедленно закрывает кладовую."},"E342.3":{"s":"{{heroName}} снимает ошибочно установленную раму и закрывает проём. Мален платит золотом за возвращённую кладовую.","f":"Портальная рама бьёт горячей энергией, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Огненная рама срывает демонтаж, но никто из допустимых бойцов не получает тяжёлого ранения. Сыр продолжает плавиться."}},"E342.4":{"s":"Вы решаете ужинать в другом месте, пока Мален доказывает демону разницу между 18 и 81. Зора пытается спасти последний кусок сыра."},"E343.1":{"s":"Вы убеждаете Лиэля заменить запоздалый дождь помощью голодающим крестьянам. Ангел выдаёт припасы, а Том впервые улыбается.","f":"Ангел не может изменить адрес уже приготовленного чуда и остаётся стоять над пустым полем. Деревня не получает помощи."},"E343.2":{"s":"Вы оставляете крестьянам часть собственной еды. Том благодарит золотом за помощь без обещаний чудес."},"E343.3":{"s":"{{heroName}} договаривается, чтобы Лиэль компенсировал урожай припасами и золотом вместо ливня. Деревня принимает решение.","f":"{{heroName}} не находит возможности превратить запоздалый дождь в полезный дар. Спор с ангелом остаётся открытым."},"E343.4":{"s":"Вы оставляете Лиэля и Тома перед пустым амбаром. Ангел всё ещё предлагает дождь, которого уже никто не просит."},"E344.1":{"s":"Вы придерживаете нагретый нимб, пока Серо выправляет вмятину. Фарил благодарит золотом за возвращённое сияние.","f":"Обод выскальзывает из держателей, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Нимб срывается при нагреве, но никто из допустимых бойцов не получает тяжёлого ранения. Ремонт приходится остановить."}},"E344.2":{"s":"Вы покупаете у паломников припасы и уходите, пока Фарил доказывает свою ангельскую природу без нимба. Серо снова разогревает обод."},"E344.3":{"s":"{{heroName}} удерживает сияющий обод на опорах, и Серо наконец выправляет его форму. Ангел благодарит золотом.","f":"Горячий нимб вырывается из крепления и причиняет {{affectedHeroName}} тяжёлое ранение.","v":{"nf":"Обод срывается с опор, но никто из допустимых бойцов не получает тяжёлого ранения. Фарил остаётся без нимба."}},"E344.4":{"s":"Вы оставляете Серо чинить небесное снаряжение. Фарил возмущённо рассказывает о втором платном входе в собственный храм."},"E345.1":{"s":"Вы поддерживаете Иару: преступление не возникает из одного возможного намерения. Судья благодарит золотом за ясное решение.","f":"Вел отказывается принимать оправдание и требует новый суд над собственными мыслями. Разбирательство продолжается."},"E345.2":{"s":"Вы передаёте припасы соседу, которому Вел так и не навредил. Он благодарит золотом, а Велу советуют начать с извинения."},"E345.3":{"s":"{{heroName}} помогает Велу отделить вину за мысль от ответственности за поступок. Судья платит золотом за законченный разговор.","f":"Вел продолжает требовать наказания за неосуществлённый замысел, несмотря на объяснения. Спор не разрешён."},"E345.4":{"s":"Вы оставляете Иару решать дело человека, который обвиняет себя в несделанном. Вел вновь спрашивает о праве на наказание."},"E346.1":{"s":"Вы обнаруживаете, что колокол реагирует на скрытую трещину в собственной печати, а не на паломников. Сиэль благодарит золотом за разгадку.","f":"Паломники считают расследование обвинением в лжи и зовут вооружённых защитников. Начинается стычка."},"E346.2":{"s":"Вы оставляете святилищу припасы для ремонта треснувшего колокола. Сиэль благодарит золотом за помощь."},"E346.3":{"s":"{{heroName}} выявляет ошибочную настройку колокола, из-за которой тот звонил на любой голос. Сиэль награждает золотом.","f":"Повреждённая печать отвечает резким звоном, причиняя {{affectedHeroName}} тяжёлое ранение.","v":{"nf":"Колокол срабатывает опасно, но никто из допустимых бойцов не получает тяжёлого ранения. Его показаниям пока нельзя верить."}},"E346.4":{"s":"Вы не испытываете честность отряда на неисправном колоколе. Сиэль прикрывает трещину тканью и прекращает приём паломников."},"E347.1":{"s":"Вы укрываете Иарала в сарае и встречаете охотников прежде, чем те успевают развернуть сети. Ангел благодарит золотом за защиту.","f":"Охотники находят сарай и зовут подкрепление. Начинается битва."},"E347.2":{"s":"Вы отдаёте Иаралу припасы и показываете скрытую тропу от сарая. Ангел благодарит золотом за возможность уйти от преследования."},"E347.3":{"s":"{{heroName}} перехватывает охотников у развилки, не дав им добраться до сарая. Иарал благодарит золотом.","f":"В скрытой засаде {{affectedHeroName}} получает тяжёлое ранение от ловчей сети.","v":{"nf":"Охотники срывают перехват, но никто из допустимых бойцов не получает тяжёлого ранения. Сарай остаётся под угрозой."}},"E347.4":{"s":"Вы уходите, не вмешиваясь в охоту за раненым ангелом. Неми закрывает за Иаралом дверь сарая."},"E348.1":{"s":"Вы доказываете, что нынешняя дорога существует по более позднему праву, чем древняя карта неба. Караван платит золотом за открытый проезд.","f":"Эс не признаёт никаких наземных поправок к воздушному маршруту. Облако остаётся на дороге."},"E348.2":{"s":"Вы платите Эсу за временный проход через его низкое облако. Караванщики возмущённо наклоняют головы, проходя под небесным контролёром."},"E348.3":{"s":"{{heroName}} сопоставляет дату строительства тракта и небесную карту, обнаруживая ошибку юрисдикции. Эс выдаёт золото за разрешённый спор.","f":"{{heroName}} не находит официальной отмены старой воздушной дороги. За проверку взыскивают золото, облако не уходит."},"E348.4":{"s":"Вы обходите низкое облако по обочине. Эс всё ещё требует убрать повозки с участка трёхсотлетнего неба."},"E349.1":{"s":"Вы раскладываете монеты кучками, чтобы драконий хвост не сбивал счёт, и Кхар наконец закрывает ведомость. Купцы благодарят золотом.","f":"Молодой дракон снова чихает в самую неподходящую минуту. Заново считать тысячи монет никто уже не хочет."},"E349.2":{"s":"Вы покупаете припасы у купцов, ожидающих возврата залога. Кхар начинает отсчёт с первой монеты в очередной раз."},"E349.3":{"s":"{{heroName}} организует отдельные коробки для каждого разряда монет, не оставляя хвосту места для путаницы. Купцы благодарят золотом.","f":"{{heroName}} не может заставить дракона перестать перекладывать монеты, и за неудачную проверку казна теряет золото."},"E349.4":{"s":"Вы уходите до следующего драконьего чиха. Кхар уже произносит число девять тысяч девяносто девять."},"E350.1":{"s":"Вы спрашиваете яйцо, что мешает ему появиться на свет, и получаете наконец осмысленный ответ. Рааш благодарит припасами за разговор.","f":"Скорлупа резко толкает приближающегося, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Яйцо опасно вздрагивает, но никто из допустимых бойцов не получает тяжёлого ранения. Ответа на вопрос вы не получаете."}},"E350.2":{"s":"Вы оставляете хранителям припасы, чтобы они не торопили вылупление. Рааш платит золотом за терпение."},"E350.3":{"s":"{{heroName}} обнаруживает, что зародыш здоров, но магическая оболочка ещё не готова треснуть. Рааш благодарит золотом за диагноз.","f":"Защитная скорлупа даёт магический толчок, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Скорлупа отталкивает исследователей, но никто из допустимых бойцов не получает тяжёлого ранения. Причина задержки не установлена."}},"E350.4":{"s":"Вы оставляете Рааша ждать согласия изнутри огромного яйца. На прощание оттуда доносится твёрдое «позже»."},"E351.1":{"s":"Вы прослеживаете след плаща до заброшенного поста и находите там золото, оставленное провокатором. Варраш впервые сомневается в чешуе.","f":"След приводит к вооружённой засаде, устроенной тем, кто подбросил улику. Начинается стычка."},"E351.2":{"s":"Вы отдаёте заставе припасы для раненого гонца, и офицер платит золотом за своевременную помощь."},"E351.3":{"s":"{{heroName}} сопоставляет показания гонца с гербом и выясняет, кто хотел поссорить два дома. Посол благодарит золотом за предотвращённый конфликт.","f":"{{heroName}} не находит, кому было выгодно оставлять столь очевидную улику. Варраш по-прежнему требует расследования вторжения."},"E351.4":{"s":"Вы не вступаете в спор драконидов из-за красной чешуи. Раненый гонец снова повторяет рассказ о человеке в плаще."},"E352.1":{"s":"Вы читаете Мараку летопись, не пропуская ни одного окончания. Старый дракон благодарит золотом за несколько часов настоящего слушания.","f":"Марак прерывает чтение после первой же пропущенной строки и требует возвращения Саары. Награды не будет."},"E352.2":{"s":"Вы покупаете у Саары припасы перед её отъездом. Библиотекарь торопливо отмечает страницу, на которой остановился Марак."},"E352.3":{"s":"{{heroName}} не просто читает хронику, но обсуждает с Мараком старые события, которые тот помнит лично. Дракон благодарит золотом и припасами.","f":"Марак ловит {{heroName}} на неверном имени в хронике и прекращает обсуждение. Страницу приходится читать заново."},"E352.4":{"s":"Вы желаете старому дракону внимательного чтеца. Марак ворчит, что хороший слушатель не должен глотать окончания."},"E353.1":{"s":"Вы убеждаете Раша и Кева сделать выход и кладовую общими, а мелом обозначить только личные углы. Илла благодарит золотом.","f":"Два дракона не могут поделить даже дым от костра и призывают охрану своих половин. Начинается стычка."},"E353.2":{"s":"Вы отдаёте Илле припасы для ещё одного дня переговоров, а она платит золотом за возможность не переносить еду через черту."},"E353.3":{"s":"{{heroName}} устанавливает право прохода через левую половину и доступа к кладовой справа. Оба дракона соглашаются, Илла благодарит золотом.","f":"{{heroName}} не может договориться о праве на эхо, которое слышно во всей пещере. За повторное разбирательство требуют золото."},"E353.4":{"s":"Вы оставляете Раша и Кева спорить, кому принадлежит дым. Илла сидит у меловой линии с подносом еды."},"E354.1":{"s":"Вы идёте рядом с Кешем по подвесному мосту, не торопя ни одного шага. Курьер вручает донесения и благодарит золотом.","f":"На середине переправы {{affectedHeroName}} получает тяжёлое ранение от сорвавшегося крепления.","v":{"nf":"Мост опасно раскачивается, но никто из допустимых бойцов не получает тяжёлого ранения. Кеш возвращается на берег."}},"E354.2":{"s":"Вы отдаёте Кешу припасы для длинного обхода, а курьер благодарит золотом за возможность не переходить мост."},"E354.3":{"s":"{{heroName}} показывает Кешу, как смотреть на дальний край, а не вниз, и проводит его через мост. Раана благодарит золотом.","f":"При резком порыве ветра {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Переправа срывается из-за ветра, но никто из допустимых бойцов не получает тяжёлого ранения. Донесения остаются на прежнем берегу."}},"E354.4":{"s":"Вы оставляете Кеша перед мостом, который он боится перейти. Курьер молча прячет донесения поглубже в сумку."},"E355.1":{"s":"Вы сверяете документы Рука и возвращаете овцу законному пастуху. Зверолюд благодарит припасами, а Бенс хмуро смотрит на бумаги.","f":"Бенс отказывается отдавать овцу даже после проверки документов. Спор остаётся на месте."},"E355.2":{"s":"Вы платите Руку за овцу и оставляете её Бенсу, не нарушив право прежнего хозяина. Фермер благодарит припасами."},"E355.3":{"s":"{{heroName}} подтверждает право Рука на стадо и предлагает оформить передачу овцы Бенсу отдельно. За точное решение отряду выдаётся золото.","f":"{{heroName}} обнаруживает несоответствие в старом рисунке ягнёнка, и спор возвращается к исходной точке. На проверку уходят золотые монеты."},"E355.4":{"s":"Вы оставляете овцу между двумя пастухами. Она наконец перегрызает верёвку, словно решив воспользоваться собственным правом выбора."},"E356.1":{"s":"Вы находите скрытый проход за сложенным поленницей и попадаете в трактир. Мира благодарит припасами за удачную догадку.","f":"Обыск всех стен ничего не даёт, а плотник Барс лишь пожимает плечами с крыши. Ужина нет."},"E356.2":{"s":"Вы платите Мире за подсказку и проходите через невидимый с дороги вход. Лисица выдаёт припасы вместе с горячим ужином."},"E356.3":{"s":"{{heroName}} замечает, как повар несёт подносы через люк под навесом. Отряд попадает внутрь и получает припасы.","f":"{{heroName}} видит лишь пустые окна, через которые исчезают тарелки. Вход найти не удаётся."},"E356.4":{"s":"Вы выбираете трактир с обычными дверями и оставляете Миру развлекаться новым кругом гостей. Барс на крыше одобрительно кивает."},"E357.1":{"s":"Вы убеждаете Брама позволить Лисе взять лишь несколько листьев, не погубив цветок на могиле брата. Травница благодарит золотом.","f":"Брам не верит, что растение переживёт срез, и остаётся на посту у единственного цветка. Лекарства нет."},"E357.2":{"s":"Вы отдаёте Лисе припасы на поиски другого средства, и она благодарит золотом за время, которое это даст больному."},"E357.3":{"s":"{{heroName}} находит способ отделить лекарственную часть корня без гибели цветка. Брам соглашается, а Лиса платит золотом.","f":"Брам воспринимает попытку взять цветок как нападение и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Брам останавливает попытку сбора, но никто из допустимых бойцов не получает тяжёлого ранения. Цветок остаётся на могиле."}},"E357.4":{"s":"Вы оставляете Брама сторожить цветок на могиле. Лиса ещё раз спрашивает, можно ли спасти больного, не отняв чужую память."},"E358.1":{"s":"Вы помогаете Шеру добраться до безопасного дома, не позволяя Кроту назначить новую ставку. Лекарка Пума благодарит золотом.","f":"Шер ввязывается в новый спор по пути и отказывается от сопровождения. Последняя жизнь остаётся на его совести."},"E358.2":{"s":"Вы отдаёте Пуме припасы для лечения Шера, а она благодарит золотом за помощь вместо новых ставок."},"E358.3":{"s":"{{heroName}} сопровождает Шера до лекаря, отвлекая от букмекеров и сомнительных дуэлей. Пума благодарит золотом.","f":"На пути к лекарю {{affectedHeroName}} получает тяжёлое ранение, защищая Шера от новой неприятности.","v":{"nf":"Шер снова срывается в опасную авантюру, но никто из допустимых бойцов не получает тяжёлого ранения. Сопровождение прекращается."}},"E358.4":{"s":"Вы отказываетесь ставить на последнюю жизнь Шера. Крот возмущённо закрывает книгу, а Пума наконец улыбается."},"E359.1":{"s":"Вы признаёте силу старой расписки и убеждаете Дила начать выплаты по долгу семьи. Омар благодарит золотом за решение.","f":"Дил отвергает семьдесят двухлетнее требование и просит новый суд. Согласия нет."},"E359.2":{"s":"Вы платите часть долга вместо Дила, и Омар ставит отметку на старой расписке. Купец благодарит, но спор о наследовании долга ещё не исчез."},"E359.3":{"s":"{{heroName}} проверяет подпись, печати и условие передачи долга семье. Дил принимает вывод, Омар платит золотом за экспертизу.","f":"{{heroName}} обнаруживает спорное слово в обгоревшей части расписки, а стороны требуют возместить расходы. Казна теряет золото."},"E359.4":{"s":"Вы оставляете Омара с распиской, пережившей должника, и Дила — с семейным спором. Старый долг всё ещё не погашен."},"E360.1":{"s":"Вы ждёте, пока Торн дочитает последний абзац, и Сова делится припасами за терпение. Медведь закрывает книгу с тяжёлым вздохом.","f":"Торн обнаруживает, что роман продолжается вторым томом, и отказывается освобождать библиотеку. Припасов отряду не достаётся."},"E360.2":{"s":"Вы покупаете припасы у ожидающих читателей, пока из библиотеки слышится драматическое чтение. Торн переворачивает очередную страницу."},"E360.3":{"s":"{{heroName}} выясняет у Совы точное число оставшихся страниц и помогает устроить очередь к нужным картам. Благодарные посетители платят золотом.","f":"{{heroName}} узнаёт, что Торн начал перечитывать любимую главу. Предсказать время открытия не удаётся."},"E360.4":{"s":"Вы уходите искать карты в другой библиотеке. Из-за закрытой двери слышится сердитое: «Не открывай её!»"}});
export { OUTCOMES_E291_E360 };
